    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "http://m.ltxs.la/";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".nav li a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 2; i < a.length-1 ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/1\./,'{{page}}.');      
        push(title, url, size);
    }
} else {
